export const eco6Tasks={"farming": [{"id": "compare", "title": "Predict and interpret the mechanism", "kind": "farming", "type": "compare", "cases": [["0", "Reducing movement can increase growth from the same intake by…", ["Reducing energy transferred through activity", "Creating new energy from nothing", "Eliminating all respiration"], 0, "An energy account must retain the other processes."], ["1", "Controlling surroundings can reduce energy used for…", ["Replacing every need for feed", "Maintaining body temperature", "Creating atoms"], 1, "Conditions and the animal matter; no unlimited heating rule follows."], ["2", "High-protein feed can support growth because it supplies…", ["An automatic cure for every disease", "Only empty space", "Amino acids for protein synthesis"], 2, "Growth still depends on a suitable overall diet and conditions."]]}, {"id": "calculate", "title": "Calculate a fresh result", "kind": "farming-data", "type": "numeric", "prompt": "Fresh120 energy units:25 activity,35 thermal,40 other. Calculate retained units.", "answer": 20, "unit": "energy units", "reasonChoices": ["120−25−35−40", "Reverse the required comparison", "Use one universal result for every real system"], "reason": 0, "why": "Use the supplied original quantities and the stated accounting boundary."}, {"id": "model", "title": "Compare all four controlled model settings", "kind": "farming-model", "type": "experiment", "experiment": "farming", "why": "Predict, reveal and record all four settings, then choose the limited interpretation."}], "fisheries": [{"id": "compare", "title": "Predict and interpret the mechanism", "kind": "fisheries", "type": "compare", "cases": [["0", "Why retain breeding fish?", ["So reproduction can help replenish stocks", "To guarantee an unlimited catch instantly", "Because no fish ever die naturally"], 0, "Recruitment depends on surviving breeding populations and conditions."], ["1", "A suitable larger mesh can help by…", ["Eliminating all environmental effects", "Allowing smaller juveniles to escape", "Catching every juvenile first"], 1, "Size selectivity can protect future breeders."], ["2", "A quota primarily limits…", ["Only the colour of fish", "Every fish’s exact growth rate", "The permitted catch"], 2, "Catch limits differ from mesh selectivity."]]}, {"id": "calculate", "title": "Calculate a fresh result", "kind": "fisheries-data", "type": "numeric", "prompt": "Fresh80 adults,30 caught, new recruits40% of surviving adults. Calculate recruits.", "answer": 20, "unit": "model recruits", "reasonChoices": ["(80−30)×0.4", "Reverse the required comparison", "Use one universal result for every real system"], "reason": 0, "why": "Use the supplied original quantities and the stated accounting boundary."}, {"id": "model", "title": "Compare all four controlled model settings", "kind": "fisheries-model", "type": "experiment", "experiment": "fisheries", "why": "Predict, reveal and record all four settings, then choose the limited interpretation."}], "biotechnology": [{"id": "compare", "title": "Predict and interpret the mechanism", "kind": "biotechnology", "type": "compare", "cases": [["0", "Fusarium used for mycoprotein is a…", ["Fungus", "Genetically modified human organ", "Photosynthetic rice seed"], 0, "Distinguish the organism from its food product."], ["1", "Its GCSE production conditions include…", ["Only pure insulin as its food", "Glucose syrup and aerobic conditions", "No carbon source and no metabolism"], 1, "Oxygen is supplied for this aerobic process."], ["2", "After fungal biomass grows it is…", ["Automatically identical to every medicine", "Ignored while only the air is packaged", "Harvested and purified"], 2, "The biomass is processed into the food product."]]}, {"id": "calculate", "title": "Calculate a fresh result", "kind": "biotechnology-data", "type": "numeric", "prompt": "Fresh60 supplied units give30 product units. Calculate output/input ratio.", "answer": 0.5, "unit": "ratio", "reasonChoices": ["30÷60", "Reverse the required comparison", "Use one universal result for every real system"], "reason": 0, "why": "Use the supplied original quantities and the stated accounting boundary."}, {"id": "model", "title": "Compare all four controlled model settings", "kind": "biotechnology-model", "type": "experiment", "experiment": "biotechnology", "why": "Predict, reveal and record all four settings, then choose the limited interpretation."}]};
export const tasksForEco6=k=>eco6Tasks[k];export const validEco6=(c,a)=>a!==''&&a!==null&&a!==undefined&&Number(a)===c[3];export const numericEco6=(v,a)=>v!==''&&v!==null&&v!==undefined&&Number.isFinite(Number(v))&&Math.abs(Number(v)-a)<.001;export const advanceEco6=(r,n,v)=>Number.isInteger(n)&&n>=0&&n<r.length&&r[n]===v?n+1:n;
export const experimentOptions={farming:{a:[['free','Free movement'],['restricted','Restricted movement']],b:[['cold','Cold surroundings'],['moderate','Moderate surroundings']],labels:['Movement','Surroundings'],unit:'retained energy units'},fisheries:{a:[['20','Adult catch20'],['60','Adult catch60']],b:[['small','Small mesh'],['large','Large mesh']],labels:['Adult catch target','Mesh'],unit:'next model fish'},biotechnology:{a:[['20','20 glucose units'],['40','40 glucose units']],b:[['air','Oxygen supplied'],['none','No supplied oxygen']],labels:['Glucose supply','Oxygen'],unit:'aerobic product units'}};
export function experimentResult(kind,a,b){let o=experimentOptions[kind];if(!o||!o.a.some(x=>x[0]===String(a))||!o.b.some(x=>x[0]===b))throw new RangeError('Choose stated model settings.');if(kind==='farming'){let movement=a==='free'?20:10,thermal=b==='cold'?30:15;return{movement,thermal,other:30,value:100-movement-thermal-30};}if(kind==='fisheries'){let adults=60-Number(a),juveniles=40-(b==='small'?10:0),recruits=adults/2;return{adults,juveniles,recruits,value:adults+juveniles+recruits};}return{glucose:Number(a),oxygen:b,value:b==='air'?Number(a)/2:0};}
export const experimentCases=k=>experimentOptions[k].a.flatMap(([a])=>experimentOptions[k].b.map(([b])=>a+':'+b));export const experimentValid=(kind,v)=>experimentCases(kind).every(k=>v.observed?.includes(k))&&v.interpretation==='limited';
